package bookstore

import "sort"

// prices[g] is the cost, in cents, of a group of g distinct books.
// A single book is $8 (800c); groups of 2/3/4/5 get 5%/10%/20%/25% off.
var prices = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket.
// books contains the title (1-5) of each book in the basket.
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	return solve(counts, make(map[[5]int]int))
}

// solve returns the minimum cost to buy the books described by counts
// (copies remaining per title). The books are symmetric, so the state is
// fully captured by the counts sorted in descending order.
func solve(counts [5]int, memo map[[5]int]int) int {
	c := counts
	sort.Slice(c[:], func(i, j int) bool { return c[i] > c[j] })
	if c[0] == 0 {
		return 0
	}
	if v, ok := memo[c]; ok {
		return v
	}

	k := 0
	for _, v := range c {
		if v > 0 {
			k++
		}
	}

	best := int(^uint(0) >> 1)
	maxGroup := k
	if maxGroup > 5 {
		maxGroup = 5
	}
	// Try every possible group size and every choice of which titles to
	// take one copy from; re-sorting keeps the state canonical.
	for group := 1; group <= maxGroup; group++ {
		for mask := 0; mask < 32; mask++ {
			if popcount(mask) != group {
				continue
			}
			nc := c
			for i := 0; i < 5; i++ {
				if mask&(1<<i) != 0 {
					nc[i]--
				}
			}
			sort.Slice(nc[:], func(i, j int) bool { return nc[i] > nc[j] })
			if cost := prices[group] + solve(nc, memo); cost < best {
				best = cost
			}
		}
	}
	memo[c] = best
	return best
}

func popcount(x int) int {
	n := 0
	for x > 0 {
		n += x & 1
		x >>= 1
	}
	return n
}

